-- Generated by `pnpm decisions:seed` from docs/planning/decisions.md (decision 191): the log's
-- entries as decisions, numbered as in the log, active unless a later entry replaces them.
-- Do not edit by hand.
insert into public.decisions
  (number, statement, reason, status, decided_by_name, decided_at, origin, origin_ref)
overriding system value
values
  (200, 'Changes to slice 2.5 after an independent review, before it merged. Capture reads only threads with two or more kept messages: a top-level message nobody answered is never read on its own, so no model runs per message (176), and a decision made in unthreaded messages is not captured. A captured decision must name the author of the message it cites as who decided, so no one can write a decision into someone else''s name ("Ada decided X"), as 195 did for threads. Reconcile deletes what listening keeps past 30 days as its first step, needing only storage, so expiry does not stop when the agent is not configured. Deleting a thread''s first message in Slack (a "tombstone") deletes the copy, and every retry of a channel message is handled. Each call''s cost is recorded before its proposals, and a capture that throws counts a failure, so a repeating failure cannot spend outside the daily budget. An edit, or a message older than what was read, makes a thread due again. The prompt turns every kind of line break into " / " and defuses message markers. The note says proposals are listed in the web app for everyone, private channels included. Left as they are: a name lookup per channel message (cached per person by the adapter), and "listen" in a group DM, where nothing is kept since those events are not subscribed', 'The review found that the 30-day deletion depended on the agent''s configuration, that a deleted thread root kept its text, that unthreaded chatter cost one call per message, that a writer in a thread could put a decision in another writer''s name, and that a failure after the call could spend outside the budget. Each now has a test', 'active', 'the owner', '2026-11-25T00:00:00Z', 'import', '200')
on conflict (origin, origin_ref) where origin_ref is not null do nothing;
